                          {row.currentLocalTime}
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* 24 Hour Cells */}
                  {row.cells.map((cell) => {
                    const isColHovered = activeHoverHour === cell.refHour;

                    // 3 visual states:
                    // 1. Sleeping: muted, faded
                    // 2. Awake, no overlap: neutral awake
                    // 3. Overlap: bright emerald green
                    let cellClasses = '';
