import { MapPin, ArrowUpDown } from 'lucide-react';

interface ControlsBarProps {
  onOpenSettings: () => void;
}

export const ControlsBar: React.FC<ControlsBarProps> = ({ onOpenSettings: _ }) => {
  const { cities, referenceCity } = useTimezone();

  return (
